import json

def norm(x):
    if isinstance(x, dict):
        return {k: norm(v) for k, v in sorted(x.items())}
    if isinstance(x, list):
        return [norm(i) for i in x]
    return x

wire = json.load(open('/tmp/wire-tools.json'))
mine = json.load(open('/home/u1/workspaces/dashr/docs/v0.1.8d_artifacts/functions.json'))

wn = [t['name'] for t in wire]; mn = [t['name'] for t in mine]
print('name lists identical (incl. order):', wn == mn)

wd = {t['name']: t for t in wire}; md = {t['name']: t for t in mine}
diffs = []
for n in wn:
    w, m = norm(wd[n]), norm(md[n])
    if w == m:
        continue
    # 定位差异字段
    for field in ('description', 'parameters'):
        if w.get(field) != m.get(field):
            diffs.append((n, field))
print('tools with ANY semantic diff:', len(diffs))
for n, f in diffs:
    print(f'  DIFF {n}.{f}')
    if f == 'description':
        a, b = wd[n]['description'], md[n]['description']
        print(f'    wire  ({len(a)} chars): {a[:160]!r}')
        print(f'    mine  ({len(b)} chars): {b[:160]!r}')
EOF","description":"Recursive semantic diff wire vs transcription"}

